import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"1965年 · 伯克希尔的控股权元年","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1965年.md","filePath":"05_quotes/by-year/1965年.md"}'),u={name:"05_quotes/by-year/1965年.md"};function l(q,t,c,s,p,n){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1965年-·-伯克希尔的控股权元年" tabindex="-1">1965年 · 伯克希尔的控股权元年 <a class="header-anchor" href="#_1965年-·-伯克希尔的控股权元年" aria-label="Permalink to &quot;1965年 · 伯克希尔的控股权元年&quot;">​</a></h1><blockquote><p>&quot;买入环节占这项业务的90%。&quot;——巴菲特（35岁）</p></blockquote><p>本页收录1965年致股东信中的经典语录。这一年，巴菲特正式取得伯克希尔·哈撒韦的控股权（平均成本14.86美元/股，账面净营运资金高达19美元/股），标志着从纯粹选股者向企业控制者的历史性跨越。同时，他宣布停止接受新合伙人，合伙企业进入&quot;守成&quot;阶段。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;买入环节占这项业务的90%。&quot;</p></blockquote><blockquote><p>&quot;合伙公司是&#39;从零开始&#39;的——每年开盘时，所有资产按市值计价，我们<strong>从零开始</strong>。&quot;</p></blockquote><blockquote><p>&quot;我认为，当前规模继续扩大，很可能对未来业绩弊大于利。&quot;</p></blockquote><blockquote><p>&quot;除非环境变化（新增资金能提升业绩），或新合伙人能带来资金以外的价值，否则我<strong>不再接受新合伙人加入</strong>合伙基金。&quot;</p></blockquote><blockquote><p>&quot;我认为，任何投资管理者，无论作为经纪人、投资顾问、信托部门、投资公司等，都应明确说明试图实现的目标，以及衡量目标达成程度的标准。&quot;</p></blockquote><blockquote><p>&quot;我宁愿承受大幅跑输道指的年份，也不愿放弃集中持仓带来的长期超额收益潜力。&quot;</p></blockquote><blockquote><p>&quot;如果有100个优质机会，我愿意高度集中于自认最优的机会，即便这会导致偶尔大幅亏损——尽管业绩波动更大，但长期跑赢的幅度会更可观。&quot;</p></blockquote><blockquote><p>&quot;持有100只股票的组合（无论管理1000美元还是10亿美元）完全不符合逻辑。加入第100只股票，对组合波动的降低作用，远不及它拉低整体预期收益的负面影响。&quot;</p></blockquote><blockquote><p>&quot;我们的业务是<strong>优质收购</strong>，而非天价出售。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1965年是历史性一年：道指上涨14.2%，而合伙企业取得惊人的47.2%收益（有限合伙人36.9%），创造史上最大超额收益幅度。巴菲特在信中正式披露了伯克希尔·哈撒韦的控股之路——以7.60美元/股起步，最终以14.86美元平均成本获得控股权，此时账面净营运资金已达19美元/股纺织业务虽已衰落，但肯·蔡斯领衔的管理团队极为优秀。合伙企业净资产已达4364万美元。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1965年/翻译.html">01_letters/1965年/翻译</a> · <a href="/01_letters/1965年/核心总结.html">01_letters/1965年/核心总结</a> · <a href="/01_letters/1965年/思维导图.html">01_letters/1965年/思维导图</a></p>',20)])])}const h=o(u,[["render",l]]);export{b as __pageData,h as default};
